"""Generate the agent skill's command reference from the pltr command manifest.

    uv run python scripts/generate_skill_reference.py           # (re)write it
    uv run python scripts/generate_skill_reference.py --check   # exit 1 if stale

The skill in ``claude_skill/`` has two parts:

* hand-written: ``SKILL.md`` (auth, the output contract, safety rules,
  discovering commands, workflows), ``README.md`` and ``workflows/``;
* generated by this script: everything in ``claude_skill/reference/``, from
  the command manifest (``pltr commands list --format json``): an index, one
  file per curated top-level group (``reference/curated/<group>.md``) and one
  per ``pltr api`` namespace (``reference/api/<namespace>.md``), so an agent
  loads only the part it needs.

Running the script is the only step needed to refresh the reference, for
example after converting a command module or regenerating ``pltr api``. The
output is deterministic and doesn't depend on the terminal, the OS or the
Python version. ``tests/test_manifest/test_skill_reference.py`` fails when the
committed files are stale, and checks that every ``pltr ...`` command the
hand-written files mention exists, with the options they use
(:func:`check_hand_written`, also run by ``--check``).
"""

from __future__ import annotations

import argparse
import re
import shlex
import sys
from pathlib import Path
from typing import (
    Any,
    Dict,
    Iterator,
    List,
    Mapping,
    NamedTuple,
    Optional,
    Sequence,
    Tuple,
)

REPO_ROOT = Path(__file__).resolve().parent.parent
SKILL_DIR = REPO_ROOT / "claude_skill"
REFERENCE_DIR = SKILL_DIR / "reference"

#: Hand-written files whose `pltr ...` commands must exist (paths from the repo root).
HAND_WRITTEN = ("claude_skill/SKILL.md", "claude_skill/README.md")
HAND_WRITTEN_GLOBS = ("claude_skill/workflows/*.md",)
#: Hand-written files of which only one section is checked: (file, heading).
HAND_WRITTEN_SECTIONS = (
    ("docs/user-guide/claude-skill.md", None),
    ("README.md", "## Using pltr from agents"),
)

GENERATED_NOTE = (
    "<!-- Generated by scripts/generate_skill_reference.py from the pltr command "
    "manifest. Do not edit by hand. -->"
)

#: Options every converted command shares; entries leave them out.
SHARED_OPTIONS = {
    "profile": "--profile",
    "format": "--format",
    "output": "--output",
    "yes": "--yes",
    "page_size": "--page-size",
    "page_token": "--page-token",
    "max_pages": "--max-pages",
    "all_pages": "--all",
}

STANDARD_FORMATS = ["table", "json", "csv"]
HELP_LIMIT = 200


def build_manifest() -> Dict[str, Any]:
    from pltr.manifest import build_manifest as build

    return build()


# --------------------------------------------------------------------- text


def first_sentence(text: str, limit: int = HELP_LIMIT) -> str:
    """The first sentence of a help text, on one line, at most ``limit`` chars."""
    text = " ".join(text.split())
    match = re.search(r"(?<!\be\.g)(?<!\bi\.e)(?<!\betc)[.!?](?=\s)", text)
    if match:
        text = text[: match.end()]
    if len(text) > limit:
        text = text[: limit - 3].rsplit(" ", 1)[0].rstrip(",;:") + "..."
    return text


def _cell(text: str) -> str:
    """Text for a Markdown table cell."""
    return " ".join(text.split()).replace("|", "\\|")


def _code(text: str) -> str:
    return f"`{text}`"


def _metavar(option: Mapping[str, Any]) -> str:
    from pltr.manifest import metavar

    return metavar(option)


def long_flag(option: Mapping[str, Any]) -> str:
    from pltr.manifest import long_flag as flag

    return flag(option)


def _is_shared(entry: Mapping[str, Any], option: Mapping[str, Any]) -> bool:
    """A shared option of a converted command (one with metadata)."""
    if "sdkMethods" not in entry:
        return False  # not converted yet: list every option it has
    flag = SHARED_OPTIONS.get(option["name"])
    return flag is not None and flag in option["flags"]


def render_argument(argument: Mapping[str, Any]) -> str:
    name = str(argument["name"]).upper() + ("..." if argument["multiple"] else "")
    line = f"- {_code(name)}"
    facts = [] if argument["required"] else ["optional"]
    if "choices" in argument:
        facts.append("one of " + ", ".join(argument["choices"]))
    if "default" in argument:
        facts.append(f"default: {argument['default']}")
    if facts:
        line += f" ({'; '.join(facts)})"
    help_text = _help(argument.get("help", ""))
    return f"{line}: {help_text}" if help_text else line


#: Generated help that says nothing beyond the name and type.
_PATH_PARAMETER = re.compile(r"^Path parameter [\w.-]+\.\s*")
_JSON_INPUT = re.compile(
    r"\s*JSON \(([^)]*(?:\([^)]*\))?[^)]*)\): inline, @file\.json, or @- for stdin\."
)


def _help(text: str) -> str:
    """Help text for an entry line: the first sentence, minus boilerplate.

    Generated commands describe JSON options as `JSON (Type): inline,
    @file.json, or @- for stdin.` and untyped path parameters as `Path
    parameter x.`; the index explains JSON input once, so keep only the type.
    """
    text = _PATH_PARAMETER.sub("", " ".join(text.split()))
    text = _JSON_INPUT.sub(lambda match: f" {match.group(1)}.", text).strip()
    if text.startswith("Type: "):
        return text[len("Type: ") :]
    return first_sentence(text)


def render_option(option: Mapping[str, Any]) -> str:
    line = "- " + ", ".join(_code(flag) for flag in option["flags"])
    if option["type"] != "flag":
        line += f" {_metavar(option)}"
    facts = []
    if option["required"]:
        facts.append("required")
    if option["multiple"]:
        facts.append("repeatable")
    if "default" in option:
        facts.append(f"default: {option['default']}")
    if facts:
        line += f" ({'; '.join(facts)})"
    help_text = _help(option.get("help", ""))
    return f"{line}: {help_text}" if help_text else line


def render_option_names(options: Sequence[Mapping[str, Any]]) -> str:
    """Optional options of a generated command on one line, without help."""
    names = []
    for option in options:
        name = _code(long_flag(option))
        if option["type"] != "flag":
            name += f" {_metavar(option)}"
        names.append(name)
    return "- Options: " + ", ".join(names)


def render_facts(entry: Mapping[str, Any]) -> str:
    """The labels line: beta, destructive, paged, output, SDK/HTTP/local."""
    facts = []
    if entry.get("beta"):
        facts.append("beta")
    if entry.get("destructive"):
        facts.append("**destructive** (asks first; `--yes` skips)")
    if entry.get("paged"):
        facts.append("paged")
    formats = entry.get("outputFormats")
    if formats == ["binary"]:
        facts.append("output: binary (to `--output FILE` or a pipe)")
    elif formats == []:
        facts.append("output: text (no `--format`)")
    if entry.get("local"):
        facts.append("local (no Foundry call)")
    elif "sdkMethods" not in entry:
        facts.append("SDK: not recorded yet")
    else:
        if entry["sdkMethods"]:
            sdk = ", ".join(_code(method) for method in entry["sdkMethods"])
            facts.append(f"SDK: {sdk}")
        if entry.get("httpEndpoints"):
            http = ", ".join(_code(endpoint) for endpoint in entry["httpEndpoints"])
            facts.append(f"HTTP (direct, labeled exception): {http}")
    return "- " + " · ".join(facts)


def render_command(entry: Mapping[str, Any]) -> List[str]:
    lines = [f"### {entry['path']}", ""]
    if entry["description"]:
        lines += [entry["description"], ""]
    lines += [_code(entry["usage"]), ""]
    lines += [render_argument(argument) for argument in entry["arguments"]]
    options = [option for option in entry["options"] if not _is_shared(entry, option)]
    if entry["generated"]:
        # The SDK's optional parameters: names only (`pltr commands show` has
        # their help), so large namespaces stay small enough to load.
        lines += [render_option(option) for option in options if option["required"]]
        optional = [option for option in options if not option["required"]]
        if optional:
            lines.append(render_option_names(optional))
    else:
        lines += [render_option(option) for option in options]
    lines += [render_facts(entry), ""]
    return lines


#: `pltr api` namespaces with more commands than this get one file per resource.
SPLIT_NAMESPACE_COMMANDS = 50


class Area(NamedTuple):
    """One reference file: a curated group, an `api` namespace or resource."""

    file: str  # relative to claude_skill/reference/, e.g. "curated/dataset.md"
    title: str  # the command path it covers, e.g. "pltr dataset"
    commands: List[Mapping[str, Any]]

    @property
    def generated(self) -> bool:
        return self.title.split()[1:2] == ["api"]


def areas(manifest: Mapping[str, Any]) -> List[Area]:
    """The reference files and the (visible) commands each one covers.

    One file per curated top-level group (`curated/<group>.md`) and one per
    `pltr api` namespace (`api/<namespace>.md`); a namespace with more than
    SPLIT_NAMESPACE_COMMANDS commands gets one file per resource instead
    (`api/<namespace>/<resource>.md`), so every file stays small enough to
    load on its own.
    """
    curated: Dict[str, List[Mapping[str, Any]]] = {}
    api: Dict[str, List[Mapping[str, Any]]] = {}
    for entry in manifest["commands"]:
        if entry["hidden"]:
            continue
        segments = entry["path"].split()[1:]
        if segments[0] == "api":
            api.setdefault(segments[1], []).append(entry)
        else:
            curated.setdefault(segments[0], []).append(entry)
    result = [
        Area(f"curated/{name}.md", f"pltr {name}", commands)
        for name, commands in curated.items()
    ]
    for name, commands in api.items():
        if len(commands) <= SPLIT_NAMESPACE_COMMANDS:
            result.append(Area(f"api/{name}.md", f"pltr api {name}", commands))
            continue
        resources: Dict[str, List[Mapping[str, Any]]] = {}
        for entry in commands:
            resources.setdefault(entry["path"].split()[3], []).append(entry)
        result += [
            Area(f"api/{name}/{resource}.md", f"pltr api {name} {resource}", entries)
            for resource, entries in resources.items()
        ]
    return sorted(result, key=lambda area: area.title.split())


def _sections(
    title: str, commands: Sequence[Mapping[str, Any]], depth: int
) -> List[Tuple[str, List[Mapping[str, Any]]]]:
    """Commands grouped by their parent path, cut to ``depth`` path words.

    A command whose path is the title itself (`pltr cp`, `pltr shell`) goes
    in the title's section.
    """
    top = len(title.split())
    sections: Dict[str, List[Mapping[str, Any]]] = {}
    for entry in commands:
        segments = entry["path"].split()
        parent = segments[: max(len(segments) - 1, top)][:depth]
        sections.setdefault(" ".join(parent), []).append(entry)
    return sorted(sections.items(), key=lambda item: item[0].split())


def render_area(
    area: Area, groups: Mapping[str, Mapping[str, Any]], sdk_version: str
) -> str:
    """One reference file: a heading per sub-group, an entry per command."""
    group = groups.get(area.title)
    count = len(area.commands)
    index = "../" * area.file.count("/") + "index.md"
    lines = [GENERATED_NOTE, f"# {area.title}", ""]
    if group:
        lines += [_paragraph(group.get("help") or group["description"]), ""]
    intro = f"{count} command{'s' if count != 1 else ''}"
    if area.generated:
        intro += f", generated from foundry-platform-sdk {sdk_version}"
    lines += [
        f"{intro}. Shared options (`--profile`, `--format`, `--output`, `--yes`, "
        f"paging) are left out; [index.md]({index}) explains the labels. "
        "Every option of one command: `pltr commands show <command>`.",
        "",
    ]
    depth = 99 if area.generated else 3
    sections = _sections(area.title, area.commands, depth)
    for parent, entries in sections:
        if len(sections) > 1 or parent != area.title:
            lines += [f"## {parent}", ""]
            section = groups.get(parent)
            if section and parent != area.title:
                lines += [section["description"], ""]
        for entry in entries:
            lines += render_command(entry)
    return "\n".join(lines).rstrip("\n") + "\n"


def _paragraph(text: str) -> str:
    """A group's help as Markdown: paragraphs kept, code-like lines indented."""
    blocks = []
    for block in text.split("\n\n"):
        lines = block.splitlines()
        if any(line.startswith((" ", "\t")) for line in lines[1:]):
            blocks.append("\n".join("    " + line for line in lines))
        else:
            blocks.append(" ".join(block.split()))
    return "\n\n".join(blocks)


def _area_row(area: Area, groups: Mapping[str, Mapping[str, Any]]) -> str:
    group = groups.get(area.title)
    description = group["description"] if group else ""
    if not description and len(area.commands) == 1:
        description = area.commands[0]["description"]
    return (
        f"| `{area.title}` | {len(area.commands)} | [{area.file}]({area.file}) "
        f"| {_cell(description)} |"
    )


def render_index(
    manifest: Mapping[str, Any],
    all_areas: Sequence[Area],
    groups: Mapping[str, Mapping[str, Any]],
) -> str:
    n_curated = sum(len(a.commands) for a in all_areas if not a.generated)
    n_api = sum(len(a.commands) for a in all_areas if a.generated)
    lines = [
        GENERATED_NOTE,
        "# pltr command reference",
        "",
        f"Every pltr command: {n_curated + n_api} in all, {n_curated} curated and "
        f"{n_api} generated (`pltr api`, from foundry-platform-sdk "
        f"{manifest['sdkVersion']}). Load only the file you need. To find a "
        "command, `pltr commands search <words>` is quicker; "
        "`pltr commands show <command>` prints every option of one command.",
        "",
        "## Reading an entry",
        "",
        "Each entry gives the command's description, its usage line, its "
        "arguments, the options specific to it (for `pltr api` commands, the "
        "optional ones by name only), and a line of labels:",
        "",
        "- **beta**: calls a beta Foundry endpoint. pltr passes "
        "`preview=true` itself; the endpoint may still change.",
        "- **destructive**: deletes or overwrites something. It asks for "
        "confirmation on a terminal; `--yes` skips the question. Without a "
        "terminal it fails with exit code 2 unless `--yes` is given.",
        "- **paged**: prints one page, with `nextPageToken` in JSON. "
        "`--page-token TOKEN` continues, `--max-pages N` and `--all` fetch more, "
        "`--page-size N` sets the page size.",
        "- **output: binary**: writes raw bytes to `--output FILE` or to a "
        "pipe, never to a terminal. **output: text**: no `--format` option.",
        "- **SDK**: the Foundry Platform SDK method it calls, as "
        "`FoundryClient.<path>`.",
        "- **HTTP (direct, labeled exception)**: one of the few commands that "
        "call a Foundry endpoint without the SDK.",
        "- **local**: makes no Foundry call.",
        "- **SDK: not recorded yet**: the command isn't on pltr's output "
        "contract yet, so its JSON keys, messages and exit codes may differ "
        "from the rules in SKILL.md. Its entry lists all of its options.",
        "",
        "Shared options are left out of the entries: `--profile/-p NAME`, "
        "`--format/-f table|json|csv` (default `table`, or `$PLTR_FORMAT`) and "
        "`--output/-o FILE` on every command that calls Foundry, `--yes/-y` "
        "on destructive commands and `--page-size`, `--page-token`, "
        "`--max-pages`, `--all` on paged ones. Options of type JSON take "
        "inline JSON, `@file.json` or `@-` (stdin), in the Foundry API's "
        "shape (camelCase field names).",
        "",
        "## Curated commands",
        "",
        "The polished commands for common tasks. Prefer them when they cover the task.",
        "",
        "| Group | Commands | Reference | Description |",
        "|---|---|---|---|",
    ]
    lines += [_area_row(area, groups) for area in all_areas if not area.generated]
    lines += [
        "",
        "## Generated commands: `pltr api`",
        "",
        "One command per SDK method, mirroring the SDK: `pltr api <namespace> "
        "<resource> [<sub-resource>...] <method>`. Arguments are the endpoint's "
        "path parameters, mostly RIDs.",
        "",
        "| Namespace or resource | Commands | Reference | Description |",
        "|---|---|---|---|",
    ]
    lines += [_area_row(area, groups) for area in all_areas if area.generated]
    return "\n".join(lines) + "\n"


def render_files(manifest: Optional[Mapping[str, Any]] = None) -> Dict[str, str]:
    """{path relative to claude_skill/reference/: content} for the manifest."""
    if manifest is None:
        manifest = build_manifest()
    groups = {group["path"]: group for group in manifest["groups"]}
    all_areas = areas(manifest)
    files = {"index.md": render_index(manifest, all_areas, groups)}
    for area in all_areas:
        files[area.file] = render_area(area, groups, manifest["sdkVersion"])
    return dict(sorted(files.items()))


# ------------------------------------------------------------ files on disk


def existing_files(directory: Path = REFERENCE_DIR) -> Dict[str, str]:
    """The files under the reference directory, by relative POSIX path."""
    if not directory.is_dir():
        return {}
    return {
        path.relative_to(directory).as_posix(): path.read_text(encoding="utf-8")
        for path in sorted(directory.rglob("*"))
        if path.is_file()
    }


def stale_files(rendered: Mapping[str, str], existing: Mapping[str, str]) -> List[str]:
    """Paths that are missing, different or no longer generated."""
    return sorted(
        path
        for path in set(rendered) | set(existing)
        if rendered.get(path) != existing.get(path)
    )


def write_files(rendered: Mapping[str, str], directory: Path = REFERENCE_DIR) -> None:
    """Write the reference and delete files it no longer has."""
    for path in set(existing_files(directory)) - set(rendered):
        (directory / path).unlink()
    for path, content in rendered.items():
        target = directory / path
        target.parent.mkdir(parents=True, exist_ok=True)
        with open(target, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(content)
    for folder in sorted(directory.rglob("*"), reverse=True):
        if folder.is_dir() and not any(folder.iterdir()):
            folder.rmdir()


# ----------------------------------------------- commands in hand-written docs

_SHELL_STOP = {"|", "||", "&&", ";", "&", ">", ">>", "<", "2>", "2>&1", ")", "`"}
#: Where a `pltr` invocation starts: line start, or after a space, `(`, `|`, ...
_COMMAND = re.compile(r"(?:^|(?<=[\s(|;&`]))pltr\s+")
_PLACEHOLDER = re.compile(r"^(<.*>|\.\.\.|\[.*\])$")
_ANGLE_PLACEHOLDER = re.compile(r"<[A-Za-z][\w.:-]*>")


def _strip_comment(line: str) -> str:
    """A shell line without its `# comment` (a `#` outside quotes that starts
    a word)."""
    quote = ""
    for index, char in enumerate(line):
        if quote:
            if char == quote:
                quote = ""
        elif char in "'\"":
            quote = char
        elif char == "#" and (index == 0 or line[index - 1].isspace()):
            return line[:index].rstrip()
    return line


def _markdown_snippets(text: str) -> Iterator[Tuple[int, str]]:
    """(line number, text) of code: fenced blocks (joined continuation
    lines, comments dropped) and inline code spans."""
    in_fence = False
    pending = ""
    pending_line = 0
    for number, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if stripped.startswith("```"):
            in_fence = not in_fence
            pending = ""
            continue
        if in_fence:
            stripped = _strip_comment(stripped)
            if not stripped:
                continue
            if not pending:
                pending_line = number
            if stripped.endswith("\\"):
                pending += stripped[:-1] + " "
                continue
            yield pending_line, pending + stripped
            pending = ""
        else:
            for match in re.finditer(r"`([^`]+)`", line):
                yield number, match.group(1)


def find_invocations(text: str) -> List[Tuple[int, List[str]]]:
    """Every `pltr ...` invocation in Markdown: (line number, argument words)."""
    found = []
    for number, snippet in _markdown_snippets(text):
        snippet = snippet.lstrip("$ ")
        for match in _COMMAND.finditer(snippet):
            # Quote placeholders (`<words>`, `ri.foundry.main.dataset.<id>`) so
            # the shell lexer doesn't read them as redirections.
            rest = _ANGLE_PLACEHOLDER.sub(
                lambda m: shlex.quote(m.group(0)), snippet[match.end() :]
            )
            try:
                lexer = shlex.shlex(rest, posix=True, punctuation_chars="|&;<>()")
                lexer.whitespace_split = True
                tokens = list(lexer)
            except ValueError:  # an unbalanced quote: a JSON value cut by a line
                tokens = rest.split()
            words: List[str] = []
            for token in tokens:
                if token in _SHELL_STOP or token.startswith(("|", ">", ";", "&")):
                    break
                words.append(token)
            found.append((number, words))
    return found


def check_invocation(manifest: Mapping[str, Any], words: Sequence[str]) -> List[str]:
    """Problems with one `pltr` invocation: unknown command, unknown option."""
    commands = {entry["path"]: entry for entry in manifest["commands"]}
    groups = {entry["path"] for entry in manifest["groups"]}
    path = "pltr"
    rest = list(words)
    while rest and not rest[0].startswith("-"):
        candidate = f"{path} {rest[0]}"
        if candidate in commands or candidate in groups:
            path = candidate
            rest.pop(0)
            if path in commands and path not in groups:
                break
        else:
            break
    if path not in commands:
        if rest and not rest[0].startswith("-"):
            if _PLACEHOLDER.match(rest[0]):
                return []  # `pltr <group> --help`: nothing more to check
            return [f"'{path} {rest[0]}' is not a pltr command"]
        if any(w not in ("--help", "--version") for w in rest if w.startswith("-")):
            return [f"'{path}' is a group: 'pltr {' '.join(words)}' runs no command"]
        return []
    entry = commands[path]
    flags = {flag for option in entry["options"] for flag in option["flags"]}
    flags.add("--help")
    problems = []
    for word in rest:
        if word == "--":
            break
        if word.startswith("-") and not re.fullmatch(r"-\d+(\.\d+)?", word):
            flag = word.split("=", 1)[0]
            if flag not in flags:
                problems.append(f"'{path}' has no option {flag}")
    return problems


def hand_written_texts() -> Dict[str, str]:
    """{file: text to check} for the hand-written skill files and sections."""
    texts: Dict[str, str] = {}
    for name in HAND_WRITTEN:
        path = REPO_ROOT / name
        if path.is_file():
            texts[name] = path.read_text(encoding="utf-8")
    for pattern in HAND_WRITTEN_GLOBS:
        for path in sorted(REPO_ROOT.glob(pattern)):
            texts[path.relative_to(REPO_ROOT).as_posix()] = path.read_text(
                encoding="utf-8"
            )
    for name, heading in HAND_WRITTEN_SECTIONS:
        path = REPO_ROOT / name
        if not path.is_file():
            continue
        text = path.read_text(encoding="utf-8")
        if heading is not None:
            start = text.find(heading + "\n")
            if start < 0:
                texts[name] = f"(missing section {heading!r})"
                continue
            end = text.find("\n## ", start + len(heading))
            text = text[start : end if end >= 0 else len(text)]
        texts[name] = text
    return texts


def check_hand_written(manifest: Optional[Mapping[str, Any]] = None) -> List[str]:
    """Every `pltr ...` command in the hand-written skill files must exist."""
    if manifest is None:
        manifest = build_manifest()
    problems = []
    for name, text in hand_written_texts().items():
        if text.startswith("(missing section"):
            problems.append(f"{name}: {text}")
            continue
        for number, words in find_invocations(text):
            for problem in check_invocation(manifest, words):
                problems.append(f"{name}:{number}: {problem}")
    return problems


# ---------------------------------------------------------------------- main


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument(
        "--check",
        action="store_true",
        help="Don't write; exit 1 if the reference is stale or a hand-written "
        "file mentions a command or option that doesn't exist.",
    )
    args = parser.parse_args(argv)
    manifest = build_manifest()
    rendered = render_files(manifest)
    stale = stale_files(rendered, existing_files())
    problems = check_hand_written(manifest)
    if args.check:
        for path in stale:
            print(f"stale: claude_skill/reference/{path}")
        for problem in problems:
            print(f"unknown command or option: {problem}")
        if stale:
            print("Run: uv run python scripts/generate_skill_reference.py")
        return 1 if stale or problems else 0
    write_files(rendered)
    size = sum(len(content.encode("utf-8")) for content in rendered.values())
    print(
        f"Wrote {len(rendered)} files to claude_skill/reference/ ({size:,} bytes, "
        f"{len(stale)} changed)."
    )
    for problem in problems:
        print(f"warning: unknown command or option: {problem}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
